const barriers = new Map();
function barrier(name) {
  if (!barriers.has(name)) {
    let release;
    const promise = new Promise((resolve) => { release = resolve; });
    barriers.set(name, { promise, release });
  }
  return barriers.get(name);
}
async function providerCall(operation, args = {}) {
  const call = { operation, at: Date.now(), ...args };
  onboarding.calls.push(call);
  const failure = onboarding.failures[operation];
  if (failure) { if (failure.remaining > 0) failure.remaining--; if (!failure.remaining) delete onboarding.failures[operation]; throw new Error(failure.message || 'controlled provider failure'); }
  if (onboarding.holds[operation]) await barrier(`${operation}:${onboarding.holds[operation]}`).promise;
  return call;
}
async function providerEffect(operation, args = {}) {
  const effect = { operation, at: Date.now(), ...args };
  onboarding.effects.push(effect);
  if (onboarding.holdsAfter[operation]) await barrier(`${operation}:${onboarding.holdsAfter[operation]}`).promise;
  const ambiguous = onboarding.ambiguousAfter[operation];
  if (ambiguous && ambiguous.remaining > 0) {
    ambiguous.remaining--;
    if (ambiguous.remaining === 0) delete onboarding.ambiguousAfter[operation];
    throw new Error('controlled response lost after provider effect');
  }
  return effect;
}
